from payments import issue_refund, mark_deposit_refunded


def _refund_cancelled_deposits(appointments):
    # Automatically refund deposits for cancelled appointments that haven't been refunded yet
    for appnt in appointments:
        if appnt.get('status') == 'cancelled' and appnt.get('deposit_paid') and not appnt.get('deposit_refunded'):
            issue_refund(appnt['payment_id'], appnt['deposit_amount'])
            mark_deposit_refunded(appnt['id'])


@tool
def check_appointments(email: str) -> str:
    if not is_valid_email(email):
        return 'Invalid email address. Please provide a valid email.'
    appointments = get_appointments_by_email(email)
    if not appointments:
        return 'No appointments found for this email.'
    _refund_cancelled_deposits(appointments)
    response = '**Your Appointments:**\n\n'
    for i, appnt in enumerate(appointments, 1):
        response += f'**Appointment {i}:**\n'
        response += f'- **Date:** {appnt['date']}\n'
        response += f'- **Time:** {appnt['time']}\n'
        response += f'- **Purpose:** {appnt['purpose']}\n\n'
    return response.strip()
